import { agruparBaterias, nomeDaBateria } from '../src/features/operacao/baterias';
import type { Sessao } from '../src/core/realtime/estado';

const s = (id: string, name: string, type: string, state: string, agendaId: number | null = 1): Sessao => ({ id, name, type, state, agendaId, competitors: [], sessionRevision: 0 });

describe('uma bateria com tomada e corrida', () => {
  it('junta as duas etapas em uma só bateria', () => {
    const b = agruparBaterias([s('2026-11-01-c', 'BATERIA 18:00 · CORRIDA', 'corrida', 'preparando'), s('2026-11-01-t', 'BATERIA 18:00 · TOMADA DE TEMPO', 'classificacao', 'preparando')]);
    expect(b).toHaveLength(1);
    expect(b[0].nome).toBe('BATERIA 18:00');
    expect(b[0].etapas.map((x) => x.type)).toEqual(['classificacao', 'corrida']);
    expect(b[0].atual.type).toBe('classificacao');
    expect(b[0].situacao).toBe('proxima');
  });
  it('depois da tomada a etapa atual é a corrida; ao fim fica encerrada', () => {
    const t = s('t', 'B · Tomada de Tempo', 'classificacao', 'encerrada');
    expect(agruparBaterias([t, s('c', 'B · Corrida', 'corrida', 'preparando')])[0].atual.id).toBe('c');
    expect(agruparBaterias([t, s('c', 'B · Corrida', 'corrida', 'em_andamento')])[0].situacao).toBe('viva');
    expect(agruparBaterias([t, s('c', 'B · Corrida', 'corrida', 'encerrada')])[0].situacao).toBe('encerrada');
  });
  it('sem agenda agrupa pelo nome e dia; baterias diferentes não se misturam', () => {
    const b = agruparBaterias([s('2026-11-01-a', 'X · Corrida', 'corrida', 'preparando', null), s('2026-11-01-b', 'X · Tomada de Tempo', 'classificacao', 'preparando', null), s('2026-11-01-d', 'Y · Corrida', 'corrida', 'preparando', null)]);
    expect(b).toHaveLength(2);
  });
  it('mantém nome com hífen próprio', () => {
    expect(nomeDaBateria('BATERIA FECHADA - LEANDRO · CORRIDA')).toBe('BATERIA FECHADA - LEANDRO');
  });
});
